-- Chitra Shop policy seed. Run Block 0, then Block 1, in order.
-- Block 0: cms_items table (policies live here, path='policies').
create table if not exists public.cms_items (
  path text not null,
  item_id text not null,
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  primary key (path, item_id)
);
alter table public.cms_items enable row level security;
drop policy if exists "Storefront can read CMS" on public.cms_items;
create policy "Storefront can read CMS"
  on public.cms_items for select using (true);
create index if not exists cms_items_path_idx on public.cms_items (path);
-- Block 1: seed rows. 4 cols, 4 values each. HTML content.
insert into public.cms_items (path, item_id, data, updated_at) values
(
  'policies',
  'refund-policy',
  jsonb_build_object(
    'id', 'refund-policy',
    'title', 'Refund Policy',
    'content', $policy$<p><strong>Last Updated: October 10, 2026</strong></p><p>At Chitra Shop, we want you to have a smooth and satisfying shopping experience. If you are not happy with your purchase or encounter an issue with your order, we are here to help.</p><p>This Refund Policy explains the conditions under which returns, exchanges, and refunds may be requested.</p><h2>1. Eligibility for Returns</h2><p>You may request a return or exchange if:</p><ul><li>You receive a damaged, defective, or faulty product.</li><li>You receive an incorrect product or an item different from what you ordered.</li><li>The product has a significant issue not disclosed in the description.</li><li>Your order qualifies under sale terms and consumer protection laws.</li></ul><p>To be eligible, the product should generally be unused, in original condition, with original packaging, accessories, tags, and proof of purchase where applicable.</p>
<p>Certain products may not be eligible for return due to hygiene, safety, customization, or other legitimate restrictions. Any such restrictions will be communicated clearly.</p><h2>2. Return Request Period</h2><p>Please contact us within <strong>7 days of receiving your order</strong> to request a return or exchange.</p><p>For damaged, defective, or incorrect products, please contact us as soon as possible with photographs or videos showing the issue.</p><p>Return requests submitted after this period may not be accepted unless required by applicable law.</p><h2>3. Refund Conditions</h2><p>Refunds may be approved when:</p><ul><li>Your return request has been reviewed and approved.</li><li>Your order is cancelled before dispatch and payment was made.</li><li>Chitra Shop cannot fulfil a confirmed and paid order.</li><li>A product arrives damaged, defective, or incorrect and a refund is approved.</li><li>Another circumstance qualifies for a refund under applicable law.</li></ul><p>Refunds will be issued using the original payment method where reasonably possible. If unavailable, we will coordinate an appropriate alternative with you.</p><h2>4. Non-Refundable Situations</h2><p>Unless required by law, refunds may not be available for:</p><ul><li>Products damaged through misuse, negligence, or improper handling after delivery.</li><li>Products returned without prior approval.</li><li>Items used, altered, or damaged by the customer, except manufacturing defects or legally protected reasons.</li><li>Products clearly identified as non-returnable before purchase, where lawful.</li><li>Change-of-mind requests outside our stated return conditions.</li></ul>
<h2>5. Order Cancellation</h2><p>You may request cancellation before your order is dispatched. Once an order has been dispatched, cancellation may no longer be possible, and the return process may apply instead.</p><p>If a prepaid order is successfully cancelled, the eligible refund will be processed after confirmation.</p><h2>6. Refund Processing Time</h2><p>Once a refund is approved, we will initiate processing within <strong>3-5 business days</strong>.</p><p>The time for the refunded amount to appear in your account may vary depending on your bank, wallet, payment provider, or financial institution.</p><p>If your refund has not arrived within a reasonable period, please contact our support team with your order number.</p><h2>7. Return Shipping Costs</h2><p>If you receive a damaged, defective, or incorrect product, Chitra Shop will coordinate an appropriate return or replacement arrangement and cover reasonable return shipping costs where applicable.</p><p>For other approved returns, shipping costs may be the customer's responsibility, provided this is consistent with the terms disclosed before purchase and applicable law.</p><h2>8. Exchanges and Replacements</h2><p>Where possible, we may offer a replacement or exchange instead of a refund. Replacements depend on product availability and the nature of the issue.</p><p>If a replacement is unavailable, we will discuss an appropriate refund or alternative resolution with you.</p><h2>9. How to Request a Refund</h2><p>To request a return, exchange, or refund, contact us using the contact details provided on our website. Please include:</p><ul><li>Your order number.</li><li>The product name.</li><li>The reason for your request.</li><li>Photographs or videos of the issue, if applicable.</li></ul><p>Our team will review your request and provide instructions for the next steps.</p><h2>10. Contact Us</h2><p>If you have questions about this policy or need assistance with a refund, please contact Chitra Shop through our website's contact page or the customer support details provided at checkout.</p><p>We appreciate your trust in Chitra Shop and will make reasonable efforts to resolve issues fairly and promptly.</p>$policy$,
    'enabled', true
  ),
  now()
),
(
  'policies',
  'terms-of-service',
  jsonb_build_object(
    'id', 'terms-of-service',
    'title', 'Terms of Service',
    'content', $policy$<p><strong>Last Updated: October 10, 2026</strong></p><p>Welcome to Chitra Shop. These Terms of Service govern your access to and use of our website and the purchase of products offered through our online store.</p><p>By accessing our website or placing an order, you agree to these terms. Please read them carefully before making a purchase.</p><h2>1. General Information</h2><p>Chitra Shop operates as an e-commerce store offering products for purchase through its website.</p><p>Throughout these terms, the words "we," "us," and "our" refer to Chitra Shop, while "you" and "your" refer to the customer or website visitor.</p><p>We reserve the right to update these terms when necessary. Updated terms will be published on this page, along with the revised date.</p><h2>2. Eligibility and Use of the Website</h2><p>By using our website, you confirm that you are legally capable of entering into a purchase agreement under applicable law.</p><p>You agree to use our website only for lawful purposes and not to:</p><ul><li>Engage in fraudulent purchases or payment activities.</li><li>Provide false or misleading information.</li><li>Attempt to disrupt, damage, or gain unauthorized access to our website.</li><li>Misuse our content, services, or ordering systems.</li><li>Violate any applicable laws or regulations.</li></ul>
<h2>3. Products and Descriptions</h2><p>We make reasonable efforts to display accurate product descriptions, images, specifications, and prices.</p><p>However, minor differences in colour, appearance, packaging, or presentation may occur due to screen settings, lighting, manufacturer updates, or other factors.</p><p>If a product contains a material error in its description or is significantly different from what was advertised, please contact us so we can review the issue in accordance with our Refund Policy and applicable law.</p><h2>4. Pricing and Payments</h2><p>All prices will be displayed on the website in the stated currency, generally Nepalese Rupees (NPR), unless otherwise specified.</p><p>Prices, promotions, and product availability may change without prior notice. Any change will not ordinarily affect an order that has already been accepted, except where correction is necessary for an obvious pricing error or required by law.</p><p>Payment methods available at checkout may include cash on delivery, bank transfers, digital wallets, or other supported payment services.</p><p>Orders requiring advance payment must be paid using the methods provided during checkout. We will not request sensitive payment credentials, such as your wallet PIN or banking password, through customer support.</p><h2>5. Orders and Acceptance</h2><p>Submitting an order constitutes a purchase request. An order confirmation does not necessarily mean that the order has been finally accepted or dispatched.</p><p>We reserve the right to cancel or decline an order in legitimate circumstances, including:</p><ul><li>Product unavailability.</li><li>Suspected fraudulent or unauthorized transactions.</li><li>Incorrect pricing or listing information.</li><li>Incomplete or invalid delivery details.</li><li>Other reasonable operational or legal grounds.</li></ul><p>If payment has already been received for an order that we cancel, we will arrange an appropriate refund in accordance with our Refund Policy and applicable law.</p><h2>6. Shipping and Delivery</h2><p>We aim to deliver orders within the estimated timeframe communicated during checkout or through customer support.</p><p>Delivery times are estimates and may vary due to location, courier availability, weather, public holidays, or other circumstances beyond our reasonable control.</p><p>Customers are responsible for providing accurate contact and delivery information. Additional charges or delays may occur if delivery details are incorrect or a delivery attempt fails.</p><p>For further information, please review our Shipping Policy.</p><h2>7. Returns, Exchanges, and Refunds</h2><p>Returns, exchanges, cancellations, and refunds are governed by our Refund Policy.</p><p>Nothing in these Terms of Service is intended to remove or limit any consumer rights that cannot legally be excluded under applicable law.</p><h2>8. Intellectual Property</h2><p>The website's original content, branding, logos, graphics, text, design elements, and other materials owned by Chitra Shop may not be copied, reproduced, distributed, or commercially used without prior permission, except where permitted by law.</p><p>Product names, trademarks, and materials belonging to third parties remain the property of their respective owners.</p>
<h2>9. Privacy and Personal Information</h2><p>We may collect and process information necessary to operate our store, fulfil orders, arrange deliveries, process payments, provide customer support, and improve our services.</p><p>We will handle personal information in accordance with applicable privacy laws and our published privacy practices.</p><p>Customers should review our Privacy Policy, if available, to understand how their information is collected, used, and protected.</p><h2>10. Third-Party Services</h2><p>Our website may use third-party services for payment processing, delivery, analytics, or other operational purposes.</p><p>We are not responsible for independent third-party websites or services beyond the responsibilities imposed on us by applicable law. Your use of those services may also be subject to their own terms and policies.</p><h2>11. Limitation of Liability</h2><p>To the extent permitted by applicable law, Chitra Shop will not be responsible for indirect or incidental losses arising from the use of our website or delays caused by circumstances outside our reasonable control.</p><p>Nothing in these terms excludes liability for fraud, wilful misconduct, or any liability or consumer protection right that cannot legally be excluded or limited.</p><h2>12. Changes to Products and Services</h2><p>We may update product listings, modify website features, discontinue products, or change our services as reasonably necessary.</p><p>We will honour accepted orders in accordance with the applicable purchase terms and legal obligations.</p><h2>13. Governing Law</h2><p>These Terms of Service are governed by the laws of Nepal, where applicable. Any disputes will be handled by the competent authorities or courts in accordance with applicable law.</p><h2>14. Contact Information</h2><p>If you have questions about these Terms of Service, orders, or our products, please contact Chitra Shop using the contact details provided on our website.</p><p>Thank you for shopping with Chitra Shop.</p>$policy$,
    'enabled', true
  ),
  now()
),
(
  'policies',
  'shipping-policy',
  jsonb_build_object(
    'id', 'shipping-policy',
    'title', 'Shipping Policy',
    'content', $policy$<p><strong>Last Updated: October 10, 2026</strong></p><p>At Chitra Shop, we aim to make online shopping convenient by providing a reliable order processing and delivery experience.</p><p>This Shipping Policy explains how orders are processed, shipped, and delivered.</p><h2>1. Delivery Locations</h2><p>Chitra Shop currently serves delivery locations within Nepal, subject to service availability.</p><p>Delivery availability may vary depending on your location, courier coverage, and the type of product ordered. If delivery to your address is unavailable, we will contact you to discuss possible alternatives.</p><p>International shipping, if offered, will be subject to separate arrangements and any applicable customs, duties, taxes, and import requirements.</p><h2>2. Order Processing Time</h2><p>Orders are generally processed within <strong>1-3 business days</strong> after order confirmation.</p><p>Processing may take longer during public holidays, promotional periods, stock shortages, or other circumstances that affect order preparation.</p><p>Orders placed outside business hours may begin processing on the next business day.</p>
<h2>3. Estimated Delivery Time</h2><p>Estimated delivery times depend on your location and the delivery service used. Our general delivery estimates are:</p><ul><li><strong>Kathmandu Valley:</strong> Approximately 1-3 business days after dispatch.</li><li><strong>Other major cities and towns in Nepal:</strong> Approximately 2-5 business days after dispatch.</li><li><strong>Remote areas:</strong> Approximately 3-7 business days or longer, depending on accessibility and courier availability.</li></ul><p>These are estimates, not guaranteed delivery dates. Actual delivery times may vary.</p><h2>4. Shipping Charges</h2><p>Shipping charges, where applicable, will be displayed during checkout or communicated before your order is confirmed.</p><p>Delivery fees may vary according to the destination, package size, weight, courier service, and any applicable promotional offers.</p><p>If free shipping is offered, the applicable conditions will be communicated clearly.</p><h2>5. Order Tracking</h2><p>If tracking is available for your shipment, we will provide the tracking details or delivery updates through the contact method associated with your order.</p><p>If you have not received a tracking update or need help locating your order, please contact our customer support team with your order number.</p><h2>6. Cash on Delivery and Prepaid Orders</h2><p>Cash on delivery may be available for eligible locations and orders, subject to confirmation.</p><p>For prepaid orders, dispatch will generally take place after payment is confirmed.</p><p>Customers should ensure that someone is available to receive the package and complete any payment due at delivery.</p><h2>7. Incorrect Address and Failed Deliveries</h2><p>Customers are responsible for providing an accurate delivery address, phone number, and other required details when placing an order.</p><p>If a delivery fails because the address is incorrect, the recipient is unavailable, or the courier cannot reach the customer, additional delivery attempts or shipping charges may apply.</p><p>Please contact us as soon as possible if you need to correct your delivery details. Address changes may not be possible after an order has been dispatched.</p><h2>8. Delayed or Lost Shipments</h2><p>Although we work to deliver orders within the estimated timeframe, delays may occur due to weather, transportation disruptions, courier issues, public holidays, or other circumstances beyond our reasonable control.</p><p>If your order appears significantly delayed or lost, contact us so we can investigate with the relevant delivery service and determine the appropriate next steps.</p>
<h2>9. Damaged, Missing, or Incorrect Items</h2><p>Please inspect your order when it arrives.</p><p>If your package arrives damaged, contains an incorrect product, or appears to be missing an item, contact us as soon as possible, preferably within 48 hours of delivery.</p><p>Please provide your order number and clear photographs or videos where applicable. We will review the issue and arrange an appropriate resolution in accordance with our Refund Policy and applicable law.</p><p>Reporting an issue within this timeframe helps us investigate efficiently, but it does not remove any rights you may have under applicable law.</p><h2>10. Order Cancellation Before Dispatch</h2><p>You may request cancellation before your order is dispatched. Once the shipment has been handed over to the courier, cancellation may no longer be possible.</p><p>If a prepaid order is eligible for cancellation, any applicable refund will be handled under our Refund Policy.</p><h2>11. Contact Us</h2><p>For questions about shipping, delivery estimates, tracking, or a delayed order, please contact Chitra Shop through the contact details provided on our website.</p><p>Please include your order number so we can assist you more efficiently.</p><p>Thank you for choosing Chitra Shop. We appreciate your trust and look forward to delivering your order.</p>$policy$,
    'enabled', true
  ),
  now()
)
on conflict (path, item_id) do update set
  data = excluded.data,
  updated_at = excluded.updated_at;

-- ---------- Block 2: verify ----------
-- Expect 3 rows: refund-policy, terms-of-service, shipping-policy.
select item_id,
  data ->> 'title' as title,
  length(data ->> 'content') as chars
from public.cms_items
where path = 'policies'
order by item_id;
-- End of policy seed.
